{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Rac-thalidomide in fasting healthy volunteers had probably high absolute oral bioavailability (80–100% at low doses), directly supporting F ≥ 20% under fasting conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ampicillin tablets in healthy fasting male subjects had absolute oral bioavailability of 62 ± 17% versus intravenous administration, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Proguanil absolute oral bioavailability in humans is reported as high as 60%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Pirprofen showed a high and uniform degree of oral bioavailability in volunteers, supporting a high F classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PNU-96391 had an absolute oral bioavailability of only 0.6 in healthy volunteers, providing a contradictory low-F data point.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer human absolute bioavailability evidence supports F ≥ 20%, including fasting-condition data; the single low-F analogue is outweighed by repeated supportive measurements, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the supplied evidence.",
    "Fasted-state-specific data for the query are not directly reported, and the threshold is close to 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

